INSERT INTO _migration_435_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_metabolism_s1_001', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which molecule acts as the immediate universal energy currency of cells?', 'multiple_choice', NULL, '["A. DNA","B. Glucose","C. ATP","D. NAD"]', 'C', 'ATP (adenosine triphosphate) is hydrolysed to ADP and inorganic phosphate to release energy directly for processes such as active transport and muscle contraction. Glucose and NAD store or carry energy, but that energy must be transferred to ATP during respiration before it can drive cellular work. Therefore the correct answer is C: ATP.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s1_002', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In which part of a eukaryotic cell does glycolysis take place?', 'multiple_choice', NULL, '["A. Mitochondrial matrix","B. Inner mitochondrial membrane","C. Chloroplast stroma","D. Cytoplasm (cytosol)"]', 'D', 'Glycolysis, the breakdown of glucose to pyruvate with a net gain of two ATP, occurs in the cytoplasm. The link reaction and Krebs cycle occur in the mitochondrial matrix, oxidative phosphorylation on the inner mitochondrial membrane, and the Calvin cycle in the chloroplast stroma. Therefore the correct answer is D: Cytoplasm (cytosol).', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s1_003', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'During the link reaction, each pyruvate molecule is converted into which product?', 'multiple_choice', NULL, '["A. Acetyl coenzyme A","B. Lactate","C. Oxaloacetate","D. Citrate"]', 'A', 'In the link reaction, pyruvate is decarboxylated (loses carbon dioxide) and dehydrogenated (reducing NAD), and the resulting two-carbon acetyl group combines with coenzyme A to form acetyl coenzyme A, which then enters the Krebs cycle. Therefore the correct answer is A: Acetyl coenzyme A.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s1_004', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which enzyme catalyses the fixation of carbon dioxide in the Calvin cycle?', 'multiple_choice', NULL, '["A. ATP synthase","B. RuBisCO (ribulose bisphosphate carboxylase)","C. Amylase","D. DNA polymerase"]', 'B', 'RuBisCO catalyses the carboxylation of ribulose bisphosphate (RuBP) with carbon dioxide in the chloroplast stroma, producing two molecules of glycerate-3-phosphate. ATP synthase makes ATP, amylase digests starch, and DNA polymerase replicates DNA. Therefore the correct answer is B: RuBisCO (ribulose bisphosphate carboxylase).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s1_005', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A metabolic poison allows protons to leak across the inner mitochondrial membrane without passing through ATP synthase, but does not block the electron transport chain. Predict the effect on respiration.', 'multiple_choice', NULL, '["A. Oxygen consumption and ATP synthesis both stop immediately","B. Oxygen consumption stops but ATP synthesis increases","C. Oxygen consumption continues but much less ATP is synthesised","D. Glycolysis stops because NAD cannot be regenerated"]', 'C', 'The leak uncouples oxidative phosphorylation: electrons still flow along the transport chain to oxygen, the final electron acceptor, so oxygen consumption continues. However, the proton gradient is dissipated without driving ATP synthase, so ATP yield falls sharply while glycolysis still regenerates NAD. Therefore the correct answer is C: Oxygen consumption continues but much less ATP is synthesised.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_metabolism_s1_006', 'topic_alevel_bio_metabolism', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student compares aerobic and anaerobic respiration in yeast and in mammalian muscle.', 'structured', NULL, NULL, '(a) Net gain of two ATP per glucose: four ATP are produced by substrate-level phosphorylation, but two ATP are consumed phosphorylating glucose and fructose phosphate early in the pathway. (b) NAD is a coenzyme that accepts hydrogen (protons and electrons) removed in dehydrogenation reactions, becoming reduced NAD; the reduced NAD then carries the hydrogen to the electron transport chain, where its energy drives ATP synthesis by oxidative phosphorylation. (c) Without oxygen as the final electron acceptor the electron transport chain stops, so only glycolysis operates, giving a net two ATP; pyruvate is converted to lactate, or to ethanol and carbon dioxide, simply to regenerate NAD, leaving most of the energy locked in those products.', '(a) Net gain of two ATP per glucose: four ATP are produced by substrate-level phosphorylation, but two ATP are consumed phosphorylating glucose and fructose phosphate early in the pathway. (b) NAD is a coenzyme that accepts hydrogen (protons and electrons) removed in dehydrogenation reactions, becoming reduced NAD; the reduced NAD then carries the hydrogen to the electron transport chain, where its energy drives ATP synthesis by oxidative phosphorylation. (c) Without oxygen as the final electron acceptor the electron transport chain stops, so only glycolysis operates, giving a net two ATP; pyruvate is converted to lactate, or to ethanol and carbon dioxide, simply to regenerate NAD, leaving most of the energy locked in those products.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_435_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_metabolism_s1_006_a', 'q_albio_metabolism_s1_006', 'a', 'State the net yield of ATP molecules from glycolysis per molecule of glucose, showing how the figure is obtained.', '2', 'Net gain of two ATP per glucose: four ATP are produced by substrate-level phosphorylation, but two ATP are consumed phosphorylating glucose and fructose phosphate early in the pathway.', '1'),
('sqp_q_albio_metabolism_s1_006_b', 'q_albio_metabolism_s1_006', 'b', 'Describe the role of NAD in glycolysis and the link reaction.', '2', 'NAD is a coenzyme that accepts hydrogen (protons and electrons) removed in dehydrogenation reactions, becoming reduced NAD; the reduced NAD then carries the hydrogen to the electron transport chain, where its energy drives ATP synthesis by oxidative phosphorylation.', '2'),
('sqp_q_albio_metabolism_s1_006_c', 'q_albio_metabolism_s1_006', 'c', 'Explain why anaerobic respiration releases much less energy per glucose molecule than aerobic respiration.', '2', 'Without oxygen as the final electron acceptor the electron transport chain stops, so only glycolysis operates, giving a net two ATP; pyruvate is converted to lactate, or to ethanol and carbon dioxide, simply to regenerate NAD, leaving most of the energy locked in those products.', '3');
INSERT INTO _migration_435_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_435_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_435_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_435_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_435_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_435_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_435_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_435_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_435_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_435_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_435_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_435_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
